        "pali_thai": "นะมัตถุ พุทธานัง, นะมัตถุ โพธิยา ",
        "thai_translation": "ความนอบน้อม จงมีแด่พระพุทธเจ้าทั้งหลาย,\nความนอบน้อม จงมีแด่พระโพธิญาณ, ",
