        "pali_thai": "นะโม วิมุตตานัง นะโม วิมุตติยา ฯ\n",
        "thai_translation": "ความนอบน้อม จงมีแด่ท่านผู้พ้นแล้วทั้งหลาย,\nความนอบน้อม จงมีแด่วิมุตติธรรม (ธรรมเป็นเครื่องหลุดพ้น) ฯ",
