        "pali_thai": "อิมัง โส ปะริตตัง กัต๎วา โมโร วาสะมะกัปปะยีติ ฯ",
        "thai_translation": "นกยูงนั้นได้กระทำปริตรอันนี้แล้วจึงได้สำเร็จแล้วซึ่งความเป็นอยู่แล.",
