        "pali_thai": "นาภิชานามิ สัญจิจจะ ปาณัง ชีวิตา โวโรเปตา,\n",
        "thai_translation": "มิได้รู้สึกว่าแกล้งจงใจ ทำลายชีวิตสัตว์เลย",
