        "pali_phinthu": "วิริยมฺปีติปสฺสทฺธิ- โพชฺฌงฺคา จ ตถาปเร,",
        "pali_thai": "วิริยัมปีติปัสสัทธิ- โพชฌังคา จะ ตะถาปะเร,",
        "thai_translation": "วิริยสัมโพชฌงค์, ปีติสัมโพชฌงค์, ปัสสัทธิสัมโพชฌงค์, ",
