        "pali_thai": "สะมาธุเปกขะโพชฌังคา สัตเตเต สัพพะทัสสินา,",
        "thai_translation": "สมาธิสัมโพชฌงค์, และอุเบกขาสัมโพชฌงค์เหล่านี้, \nอันพระมุนีเจ้าผู้เห็นธรรมทั้งปวงเหล่านั้น-,\n",
